INSERT INTO "public"."fishes" ("id", "name_tr", "name_en", "scientific_name", "water_type", "active_seasons", "recommended_gear", "description_tr", "description_en", "image_url", "is_active", "created_at", "limit_size", "ban_periods", "short_info_tr", "short_info_en", "favorite_baits", "primary_regions", "taste_rating", "cooking_tips_tr", "cooking_tips_en") VALUES ('00ff64bb-43cf-4b26-8cf8-bd23e80d4cf9', 'Şiraz Balığı', 'Scraper (Capoeta)', 'Capoeta capoeta', 'Tatlı Su', 'İlkbahar, Yaz', 'Şamandıralı Hassas Takım, Dip Oltası', 'Oltaya çok sert kafa vurur. Akıntılı suları sevdiği için ince takımla yakalandığında uzun süre mücadele eder.', 'Hits the line hard and fights relentlessly in river currents, making it a fun target on light float gear.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/os71jiqdb48_1784882964949.png', true, '2026-07-22 12:24:38.112653+00', 'Asgari 20 cm', '15 Mart - 15 Haziran (İç sularda)', 'Akarsu tabanındaki yosunları kazıyarak beslenen, güçlü dudaklara sahip dere balığı.', 'Stream fish with strong lips adapted for scraping algae off rocks.', 'Hamur, Haşlanmış Buğday, Mısır', 'Kızılırmak, Sakarya Nehri ve Anadolu akarsuları', '2/5 Yıldız - Çok Kılçıklı', 'Kılçık yapısı nedeniyle genelde sadece sportif amaçlı tutulur veya çizilip kızartılır.', 'Due to dense bones, mostly targeted for sport or scored deeply before frying.'), ('04a39538-4efa-49f4-8238-300bbbf1fcf9', 'Kefal (Has Kefal)', 'Flathead Grey Mullet', 'Mugil cephalus', 'Tuzlu Su', 'İlkbahar, Yaz, Sonbahar', 'Kıbrıs Sarması, Şamandıralı Takım', 'Çok ürkektir ve yemi hemen yutmaz, emer. Bu yüzden yakalaması tecrübe ister. Oltaya bindiğinde inanılmaz bir güçle fişekleyerek misinayı zorlar.', 'Very skittish and sucks the bait rather than biting it. When hooked, it puts up a very strong and energetic fight.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/nffffeldmw_1784883228532.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 20 cm', 'Yıl boyu serbest', 'Limanlarda ve nehir ağızlarında sıkça görülen, güçlü yüzücü.', 'Strong swimmer frequently seen in ports and river estuaries.', 'Taze Ekmek İçi, Hamur, Sardalya Filetosu', 'Limanlar, Marina içleri, Nehirlerin denize döküldüğü yerler', '3/5 Yıldız - Yaşadığı Suya Göre Değişir', 'Temiz sulardan yakalananları fırında veya ızgarada çok lezzetli olur.', 'Delicious baked or grilled if caught from clean waters.'), ('0619ce2f-e16e-4e06-9c93-a5907961aa66', 'İstavrit', 'Atlantic Horse Mackerel', 'Trachurus trachurus', 'Tuzlu Su', 'İlkbahar, Yaz, Sonbahar, Kış', 'Çapari, LRF (1-3g Jighead)', 'Özellikle LRF disiplinine giriş yapanların ilk gözdesidir. Gece ışık alan meralarda mikro silikonlarla avlamak inanılmaz keyiflidir.', 'The perfect target for LRF beginners. Catching them at night under illuminated piers using micro soft plastics is extremely fun.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/g5gh7k76bx5_1784889870660.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 13 cm', 'Yıl boyu serbest (Bölgesel ticari yasaklar hariç)', 'Kıyı balıkçılığının en popüler ve erişilebilir türü.', 'The most popular and accessible species in coastal fishing.', 'Yeşil/Beyaz Tüylü Çapari, Mikro Silikonlar, Kokulu Yemler (Isome)', 'İstanbul Boğazı, Marmara, Karadeniz ve Ege Kıyıları', '4/5 Yıldız - Tavada Çıtır', 'Tavada kızartması klasiktir, irileri (Sarıkanat) ızgara da yapılabilir.', 'Pan-frying is a classic; larger ones can also be grilled.'), ('0bc51838-551d-4034-8bac-123649843339', 'Mercan (Kırmızı Mercan)', 'Common Pandora', 'Pagellus erythrinus', 'Tuzlu Su', 'İlkbahar, Sonbahar', 'Tekneden Yemli Dip Takımı (Sarkıtma)', 'Genellikle tekneden yapılan avların en değerli hedefidir. Sürü halinde gezerler, dipte yemi tırtıklayarak yer. Hassas uçlu tekne kamışları (boat rod) ile avlanması keyiflidir.', 'Often the most prized target for boat fishing. Schools feed on the bottom. Best targeted with sensitive boat rods.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/vbiygi7wdv_1784891892820.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 15 cm', 'Yıl boyu serbest', 'Derin suların taşlık ve kumluk alanlarında yaşayan pembe incisi.', 'The pink pearl of deep rocky and sandy waters.', 'Karides, Sülünes, Kalamar Parçası, Madya', 'Ege Denizi (Çeşme, Seferihisar, Ayvalık)', '5/5 Yıldız - Çok Lezzetli Beyaz Et', 'Taze otlar ve zeytinyağı ile fırında veya odun ateşinde ızgarası yapılır.', 'Baked with fresh herbs and olive oil or wood-grilled.'), ('108d1466-b5cd-4d00-9e9c-09ebca47c934', 'Gümüş Balığı', 'Sand Smelt', 'Atherina boyeri', 'Tatlı Su', 'İlkbahar, Yaz', 'İnce Çapari, Şamandıralı Hassas Takım', 'Özellikle göllerde büyük sürüler oluşturur. İnce uçlu takımlarla tutması eğlencelidir, ayrıca iri avcı balıklar (Turna, Sudak) için mükemmel bir canlı yemdir.', 'Forms large schools in lakes. Fun to catch with light gear and serves as excellent live bait for larger predators.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/xcp31t1hm5_1784879124862.png', true, '2026-07-22 12:21:18.943312+00', 'Limit Yok (Sportif olarak yasal boy sınırı belirtilmemiştir)', '15 Mart - 15 Haziran (İç sularda)', 'Sürüler halinde gezen, yarı saydam ufak yapılı bir tür.', 'Small, semi-transparent schooling fish.', 'Hamur, Küçük Kurtçuklar', 'Sapanca, İznik gibi büyük göller ve barajlar', '4/5 Yıldız - Çerezlik', 'Mısır ununa bulanıp bütün olarak yağda kızartılır, cips gibi yenir.', 'Coated in cornmeal and deep-fried whole, eaten like chips.'), ('13f1c182-1c04-402f-ad75-d63713c30de7', 'Pullu Sazan', 'Common Carp', 'Cyprinus carpio', 'Tatlı Su', 'İlkbahar, Yaz, Sonbahar', 'Sazan Montajı (Hair Rig), Ağır Dip Takımı', 'Tatlı suların en efsanevi dip balıklarından biridir. Güçlü kuyruk yapısı sayesinde dip oltasına takıldığında yorucu ve heyecanlı bir mücadele sunar.', 'One of the most famous freshwater bottom dwellers, renowned for its strength.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/qyhdltxi3mo_1784881871118.png', true, '2026-07-23 18:11:18.126489+00', 'Asgari 40 cm', '15 Mart - 15 Haziran (İç sular genel av yasağı)', 'Tatlı sularımızın en yaygın, güçlü ve iri pullarla kaplı ana sazan türü.', 'The most widespread native carp species with fully scaled body.', 'Boilie, Haşlanmış Mısır, Kaplan Fıstığı, Solucan', 'Tüm baraj gölleri, göller ve yavaş akan nehirler', '4/5 Yıldız - Yağlı ve Doyurucu Et', 'Fırında sebzelerle doldurularak veya dilimlenip kızartılır.', 'Stuffed with fresh vegetables and baked or sliced and fried.'), ('15fcaeb4-3c04-4bb7-8a31-7387980582ee', 'Lagos (Kumlagosu)', 'White Grouper', 'Epinephelus aeneus', 'Tuzlu Su', 'Yaz, Sonbahar', 'Slow Jigging, Canlı Yemle Bırakma, Ağır Spin', 'Gücüyle ekipmanları test eden bir balıktır. Yemi aldığında hızla kayaların arasına girip kendini kilitler, bu yüzden vuruş alındığında hiç boşluk vermeden dipten kesilmelidir.', 'Tests equipment to its limits. When hooked, it immediately dives into rock crevices, requiring the angler to pull it up with zero slack.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/p249rd8j1m_1784890911115.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 45 cm', '15 Nisan - 15 Temmuz (Ticari', 'Akdeniz''in kayalık diplerinde yaşayan, trofe değeri çok yüksek dev.', 'Giant trophy fish living in the rocky bottoms of the Mediterranean.', 'Canlı Kalamar, Sübye, Ağır Jig Sahteleri', 'Akdeniz (Antalya, Taşucu, Hatay kıyıları)', '5/5 Yıldız - Muazzam Bir Et Kalitesi', 'Şiş, ızgara veya fırında sebzeli kavurması yapılır.', 'Prepared as skewers, grilled, or pan-roasted with vegetables.'), ('2138b6f9-6d44-4e67-b343-0c5ef6a3a5f2', 'Orkinos (Mavi Kanat)', 'Atlantic Bluefin Tuna', 'Thunnus thynnus', 'Tuzlu Su', 'Yaz, Sonbahar', 'Big Game (Ağır Trolling), Heavy Spinning', 'Sportif balıkçılığın zirvesidir. Yakalanması devasa çıkrık makineler, çok güçlü kamışlar ve saatler süren fiziksel bir mücadele gerektirir.', 'The pinnacle of sport fishing. Catching it requires massive reels, heavy rods, and hours of physical battle.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/soqw2at6a5_1784881924000.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 115 cm veya 30 kg (Özel İzin Gerektirir)', 'ICCAT kotalarına ve uluslararası yasalara tabidir', 'Açık denizlerin en hızlı ve en güçlü, trofe değeri en yüksek pelajik avcısı.', 'The fastest, strongest, and most prized pelagic predator of the open seas.', 'Canlı Uskumru, Palamut, Büyük Popper Sahteler', 'Kuzey Ege (Saros), Akdeniz açıkları', '5/5 Yıldız - Eşsiz (Sushi/Sashimi kalitesi)', 'Asla çok pişirilmemeli, ızgarada içi hafif pembe kalacak şekilde mühürlenmeli veya çiğ (sashimi) tüketilmelidir.', 'Should never be overcooked; sear on the grill leaving the center pink, or serve raw as sashimi.'), ('21cc3857-a1b3-49f7-a650-41413cefea6c', 'Karagöz (Baltabaş)', 'Two-banded Seabream', 'Diplodus vulgaris', 'Tuzlu Su', 'İlkbahar, Sonbahar', 'Şamandıralı Kayalık Takımı, LRF, Yemli Dip', 'Sargoz ile karıştırılır ancak ensesindeki kalın siyah bant en büyük farkıdır. Kayalık midyeli bölgelerde yaşar, ince takımlarla avı çok zevklidir.', 'Often confused with the White Seabream, but distinguished by a thick black band on the nape. Thrives in rocky, mussel-rich areas.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/wxviqpid8mb_1784879342734.png', true, '2026-07-22 12:23:32.945782+00', 'Asgari 21 cm', 'Yıl boyu serbest', 'Kafasındaki siyah bant ile tanınan, kayalıkların kavgacı balığı.', 'Combative fish of the rocks, recognized by the black band behind its head.', 'Boru Kurdu, Mamun, Yengeç, Midye', 'Marmara, Ege ve Akdeniz kıyıları', '4/5 Yıldız - Sıkı ve Yağlı Et', 'Marmara denizinde yakalananları ızgarada çok lezzetlidir.', 'Specimens caught in the Marmara Sea are extremely delicious on the grill.'), ('24e8c322-494a-418a-9153-ac3739f90072', 'Sarpa', 'Salema Porgy', 'Sarpa salpa', 'Tuzlu Su', 'Yaz, Sonbahar', 'İnce Şamandıralı Takım, Kıbrıs Sarması', 'Çok güçlü ve mücadeleci bir balıktır. İnce takımla avlandığında oltayı inanılmaz büker. Etçil olmadığı için klasik yemlere (kurt, karides) pek rağbet etmez.', 'Puts up a remarkably strong fight on light gear. Being herbivorous, it rarely strikes traditional baits like worms or shrimp.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/v8bdhgiof9n_1784882905792.png', true, '2026-07-22 12:24:38.112653+00', 'Limit Yok', 'Yıl boyu serbest', 'Üzerindeki altın sarısı çizgilerle dikkat çeken otçul sürü balığı.', 'Herbivorous schooling fish distinguished by its golden yellow stripes.', 'Taze Ekmek İçi, Yosun, Hamur', 'Ege ve Akdeniz kayalıkları, Liman içleri', '2/5 Yıldız - Ota Dayalı Yoğun Tat', 'Karnı yosun dolu olduğu için tutulur tutulmaz temizlenmezse eti çok acılaşır.', 'Guts are full of algae; must be cleaned immediately upon catching to prevent the meat from becoming bitter.'), ('2c78d034-e8ec-4160-acbc-de02b7b1ca3c', 'Kızılkanat', 'Rudd', 'Scardinius erythrophthalmus', 'Tatlı Su', 'İlkbahar, Yaz', 'Şamandıralı İnce Takım, LRF', 'Durgun ve bitkili göllerde şamandıralı oltalarla avlanması özellikle genç balıkçılar için çok keyifli olan tatlı su balığıdır.', 'A classic float-fishing species found in vegetated freshwater lakes.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/dstl2ofu3_1784890133993.png', true, '2026-07-23 18:08:50.859454+00', 'Asgari 15 cm', '15 Mart - 15 Haziran', 'Parlak kırmızı yüzgeçleri ve gümüş gövdesiyle sazlıkların sevimli sakini.', 'Beautiful silver fish with bright red fins inhabiting reed beds.', 'Ekmek İçi, Solucan, Mısır, Küçük Sinek Sahteleri', 'Sapanca, Terkos, Uluabat, Manyas ve tüm göl sazlıkları', '3/5 Yıldız - Kılçıklı Ancak Tatlı Et', 'Tavada ince çizikler atılarak bol yağda kızartılır.', 'Deep fried with cross cuts along the body.'), ('2eea6ee2-69c7-4bfc-b8eb-b6035d8dd0c3', 'Mezgit', 'Whiting', 'Merlangius merlangus', 'Tuzlu Su', 'Kış, İlkbahar', '3-4 İğneli Yemli Dip Takımı', 'Açgözlü bir balıktır, yem ayırt etmez. Oltaya genellikle ikili üçlü biner. Kış aylarında kıyıdan derin yerlere atılarak çok rahat avlanabilir.', 'Very greedy, not picky about bait. Often caught two or three at a time on multi-hook rigs. Easily targeted from shore in winter.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/v8hwjgauv7e_1784894692163.png', true, '2026-07-22 12:23:32.945782+00', 'Asgari 13 cm', 'Yıl boyu serbest', 'Karadeniz ve Marmara''nın en iştahlı ve kolay avlanan dip balığı.', 'The most voracious and easily caught bottom fish of the Black Sea and Marmara.', 'Tavuk Göğsü, Midye Eti, Karides', 'Karadeniz ve Marmara kıyıları', '4/5 Yıldız - Tavuk Eti Gibi Löp', 'Mısır unuyla tavada kızartması veya mayonezli sosa batırılarak yenmesi meşhurdur.', 'Famous for being pan-fried with cornmeal; great dipped in mayonnaise-based sauces.'), ('3149ba0d-2b0c-4559-b6f0-e0a833e1f4f6', 'Sudak (Uzun Levrek)', 'Zander', 'Sander lucioperca', 'Tatlı Su', 'İlkbahar, Sonbahar', 'Spinning, LRF, Jigging', 'Gündüzleri derin sulara çekilir, sabah suyu ve akşam karanlığında sığlıklara avlanmaya çıkar. Silikon yemleri dipten zıplatarak (jigging) avlamak çok zevklidir.', 'Retreats to deep water during the day, hunts in shallows at dawn and dusk. Catching them by bouncing soft plastics on the bottom is thrilling.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/9vbvudyq1r_1784882981829.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 26 cm', '15 Mart - 30 Nisan (İç sularda)', 'Büyük baraj göllerinin vampir dişli, karanlığı seven zeki avcısı.', 'Intelligent, vampire-toothed predator of large reservoir lakes, active in low light.', 'Silikon Yemler (Jighead), Canlı Gümüş Balığı', 'Hirfanlı, Sarıyar ve diğer büyük baraj gölleri', '5/5 Yıldız - Tatlı Suyun En Lezzetlisi', 'Kılçıksız löp et olduğu için fileto edilip tereyağında kızartılması eşsizdir.', 'Yields boneless fillets; pan-frying in butter is unmatched.'), ('33cc8c6a-f254-4af5-b428-b07bfb50e077', 'Kalkan', 'Turbot', 'Scophthalmus maximus', 'Tuzlu Su', 'İlkbahar, Kış', 'Ağır Dip Takımı (Özel Kalkan İğneli)', 'Avcılığı çok sabır gerektirir. Kış ve ilkbahar aylarında kumsallardan veya dalgakıranlardan uzak atış (surfcasting) ile taze yem kullanılarak aranır.', 'Requires great patience. Targeted via surfcasting from sandy beaches using fresh bait fish during winter and spring.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/yqpuzb40t8_1784879296390.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 45 cm', '15 Nisan - 15 Haziran', 'Karadeniz''in kumluk diplerine gizlenen, üzeri düğmeli yassı balık.', 'Flatfish of the Black Sea with bony tubercles, hiding in sandy bottoms.', 'İstavrit, Mezgit, Taze Hamsi Fileto', 'Batı Karadeniz, İstanbul Boğazı girişleri', '5/5 Yıldız - Üst Düzey Lezzet', 'Tavada kızartılır veya fırında sebzeli olarak pişirilir.', 'Fried in a pan or baked in the oven with vegetables.'), ('3864b018-a5bf-4371-b0b4-c11024826ee0', 'Sargoz (Karagöz)', 'White Seabream', 'Diplodus sargus', 'Tuzlu Su', 'İlkbahar, Sonbahar', 'Şamandıralı Takım, LRF, Yemli Dip', 'Kayalıkların arasında yaşadığı için avlanması zordur; takımı kayalara taktırmadan yemi ulaştırmak ustalık ister. LRF takımlarına harika kafa atar.', 'Difficult to catch as they live among rocks. Provides a great head-banging fight on LRF setups.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/80humdg6lyb_1784882276317.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 21 cm', 'Yıl boyu serbest', 'Kayalık bölgelerin siyah dikey çizgili, güçlü çeneli efendisi.', 'Strong-jawed master of rocky shores, recognized by its black vertical stripes.', 'Yengeç, Sülünes, Madya, Karides', 'Ege ve Akdeniz kayalık kıyıları', '4/5 Yıldız - Beyaz ve Sıkı Et', 'Fırında zeytinyağı ve limonla ya da mangalda bütün olarak pişirilir.', 'Baked with olive oil and lemon, or grilled whole on charcoal.'), ('3ceba5ba-4eb6-476d-ab95-dfa041851ce0', 'Fırat Turnası', 'Manger (Barbus)', 'Luciobarbus esocinus', 'Tatlı Su', 'İlkbahar, Yaz, Sonbahar', 'Ağır Dip Oltası, Kaşık, Canlı Yem Düzenekleri', 'Güneydoğu ve Doğu Anadolu sularının en büyük trofe balığıdır. Oltaya bindiğinde bükülmez bir direnç gösterir ve ağır takımlarla avlanır.', 'The largest trophy freshwater species of the Euphrates basin, known for its massive power.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/u1x40jqis5e_1784889846311.png', true, '2026-07-23 18:08:50.287898+00', 'Asgari 50 cm', '15 Mart - 15 Haziran', 'Fırat ve Dicle nehirlerinin 100 kg''a ulaşabilen dev efsanevi avcısı.', 'Legendary giant predator of the Euphrates and Tigris rivers reaching up to 100 kg.', 'Canlı Balık, Hamur, Ağır Metal Kaşıklar, Sülük', 'Atatürk Barajı, Keban Barajı, Birecik, Fırat ve Dicle Nehirleri', '4/5 Yıldız - İri ve Yağlı Et', 'Fırında baharatlı buğulama veya kuşbaşı doğranıp şiş kebap yapılır.', 'Best oven-baked with herbs or grilled as skewers.'), ('3d0269ab-0140-4052-8b97-50576721c182', 'Kırlangıç', 'Tub Gurnard', 'Chelidonichthys lucerna', 'Tuzlu Su', 'İlkbahar, Sonbahar', 'Yemli Dip Takımı, Tai Rubber, Jigging', 'Göğüs yüzgeçlerinin altındaki bağımsız ışınları bacak gibi kullanarak deniz tabanında yürür. Suyun dışına çıkarıldığında kurbağa benzeri sesler çıkarır.', 'Uses modified fin rays to "walk" on the sea floor. Makes a croaking, frog-like sound when taken out of the water.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/8m39xha7var_1784879374880.png', true, '2026-07-22 12:23:32.945782+00', 'Asgari 18 cm', 'Yıl boyu serbest', 'Kelebek kanadına benzeyen mavi kenarlı göğüs yüzgeçleri olan dip balığı.', 'Bottom dweller with large, butterfly-like pectoral fins edged in blue.', 'Bütün Mamun, Sülünes, Kalamar Bacağı, Canlı Gümüş', 'Marmara Denizi, Ege açıkları', '5/5 Yıldız - Çorba ve Buğulama Ustası', 'Çorbası İskorpit kadar meşhurdur, fırında güveçte sebzeli buğulaması şahanedir.', 'Famous for soup; makes a magnificent vegetable stew in a clay pot.'), ('4148317c-f8ec-4c98-92f1-838b9173f91b', 'Kupez (Kupa)', 'Bogue', 'Boops boops', 'Tuzlu Su', 'İlkbahar, Yaz, Sonbahar', 'İnce Dip Takımı, Çapari, Şamandıralı', 'Balıkçıların "yem hırsızı" olarak bildiği türdür. Hedef balıktan önce yeme saldırıp iğneyi temizler. Sportif avcılığı ince takımlarla eğlencelidir.', 'Known to anglers as a "bait thief." Will clean a hook before the target fish can arrive. Fun to catch with ultra-light gear.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/3wuu8z72ll_1784890355015.png', true, '2026-07-22 12:23:32.945782+00', 'Limit Yok', 'Yıl boyu serbest', 'İri gözlü, sürü halinde gezen ve oltadaki yemlere ilk saldıran hırsız balık.', 'Large-eyed schooling fish, infamous for quickly stealing bait off hooks.', 'Ekmek İçi, Tavuk Göğsü, Karides', 'Tüm Ege ve Akdeniz kıyıları', '2/5 Yıldız - Yoğun Koku', 'Eti çabuk bozulur ve karnı çok koku yapar. Temizlenip kızartılması gerekir.', 'Meat spoils quickly and the guts smell strong. Must be cleaned quickly and fried.'), ('446ee4a3-3bd3-40c2-a0b9-1dd4318e6887', 'Granyöz (Sarıağız / Kaya Levreği)', 'Meagre', 'Argyrosomus regius', 'Tuzlu Su', 'İlkbahar, Yaz', 'Ağır Spin, Yemli Bırakma, Shore Jigging', 'Özellikle nehirlerin denize karıştığı acı su (brackish water) bölgelerini çok sever. Kafasının içindeki denge taşları (otolit) tespih yapımında kullanılır.', 'Particularly fond of brackish estuaries where rivers meet the sea. The large otoliths (ear stones) in its head are sometimes used to make worry beads.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/y1indi95w5_1784879092864.png', true, '2026-07-22 12:23:32.945782+00', 'Asgari 25 cm', 'Yıl boyu serbest', 'Ağzının içindeki sarı renkle bilinen, levrek boyutlarını aşan dev avcı.', 'Giant predator exceeding seabass in size, known for the yellow color inside its mouth.', 'Canlı Kefal, İri Silikon Sahteler (Jighead)', 'Ege ve Akdeniz nehir ağızları, liman girişleri', '4/5 Yıldız - Löp Beyaz Et', 'Fırında sebzelerle veya dilimlenerek ızgarada pişirilmesi mükemmeldir.', 'Excellent baked with vegetables or steaked and grilled.'), ('485cef36-2552-4c58-a61b-86ba6ae42dd9', 'Aynalı Sazan', 'Mirror Carp', 'Cyprinus carpio', 'Tatlı Su', 'İlkbahar, Yaz, Sonbahar', 'Sazan Montajı (Hair Rig), Ağır Dip Takımı', 'Özel sazan takımları, alarmlı sehpalar (rod pod) ve yüksek çekerli misinalarla günlerce süren kamp avcılığının bir numaralı hedefidir.', 'The number one target for multi-day camping trips using specialized carp gear and bite alarms.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/hit56z403ks_1784889473543.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 40 cm', 'İç sularda 15 Mart - 15 Haziran (Bölgelere göre değişir)', 'Tatlı suların en popüler, iri pullu ve mücadeleci dip balığı.', 'The most popular and combative bottom-dwelling fish of freshwaters.', 'Boilie, Haşlanmış Mısır, Kaplan Fıstığı (Tiger Nut)', 'Anadolu''daki hemen tüm gölet ve barajlar', '3/5 Yıldız - Kılçıklı fakat Lezzetli', 'Çizikler atılarak fırında kızartılır veya güveçte sebzeli buğulaması yapılır.', 'Scored and baked in the oven, or stewed with vegetables.'), ('4e5a94ec-93f4-4667-8ab3-54f30d1b0997', 'Pisi Balığı', 'European Flounder', 'Platichthys flesus', 'Tuzlu Su', 'Kış, İlkbahar, Sonbahar', 'İnce Yemli Dip Takımı, Surfcasting', 'Gözleri vücudunun tek tarafında toplanmış asimetrik bir balıktır. Kendini kuma gömerek kamufle olur. Tuza toleransı yüksektir, nehirlerin içlerine kadar girebilir.', 'An asymmetrical fish with both eyes on one side of its body. Camouflages by burying into the sand. Highly tolerant to low salinity and often enters rivers.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/mvqutez3z2r_1784895297521.png', true, '2026-07-22 12:24:38.112653+00', 'Asgari 20 cm', 'Yıl boyu serbest', 'Kalkan balığının akrabası olan, kumluklarda ve nehir ağızlarında yaşayan yassı balık.', 'A flatfish relative of the turbot, living in sandy bottoms and estuaries.', 'Boru Kurdu, Sülünes, Karides', 'Karadeniz ve Marmara kumlukları, Nehir ağızları (Acı su)', '4/5 Yıldız - Yumuşak ve Kılçıksız', 'Tavada mısır unuyla bütün kızartılır veya tereyağlı fırın yapılır.', 'Whole pan-fried with cornmeal or baked with butter.'), ('53317506-0972-427b-b5b4-cc1c8a53e2bd', 'Dülger (Peygamber Balığı)', 'John Dory', 'Zeus faber', 'Tuzlu Su', 'Kış, İlkbahar', 'Yemli Dip Takımı, Slow Jigging', 'Gövdesi kağıt gibi incedir. Avına fark edilmeden yaklaşıp vakum gibi açılan büyük ağzıyla yutarak beslenir. Efsaneye göre gövdesindeki iz, Hz. Süleyman veya Hz. İsa nın parmak izidir.', 'Paper-thin body. Approaches prey unnoticed and sucks them in with a highly extensible mouth.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/5w5impl125_1784889751684.png', true, '2026-07-22 12:23:32.945782+00', 'Limit Yok (Sportif sınır bulunmuyor)', 'Yıl boyu serbest', 'Gövdesindeki devasa siyah beneği ile bilinen, derin su kamuflaj ustası.', 'Deep-water camouflage master known for the giant black spot on its flank.', 'Canlı İstavrit, İzmarit', 'Marmara, Ege ve Akdeniz derinlikleri', '5/5 Yıldız - Şeflerin Gözdesi', 'Kılçıksız harika bir eti vardır. Tavada tereyağı ile mühürlenerek pişirilir.', 'Boneless, premium meat. Best pan-seared with butter.'), ('53a59812-fd77-4f17-818e-24508b468b8e', 'Palamut', 'Atlantic Bonito', 'Sarda sarda', 'Tuzlu Su', 'Sonbahar', 'Sırtı (Trolling), Ağır Spin, Palamut Çaparisi', 'Eylül ayında Karadeniz''den Marmara''ya göçü başlar. Boğazda sırtı çekerek veya kıyıdan ağır kaşıklarla (spin) yapılan avcılığı çok bereketlidir.', 'Migration starts in September. Trolling in the Bosphorus or shore spinning with heavy metal spoons are highly productive.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/srio4e5zwkn_1784895269695.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 25 cm (Torik için 38 cm)', '15 Nisan - 31 Ağustos', 'Karadeniz ve Marmara''nın göçmen, yırtıcı ve sürüler halinde gezen efsanesi.', 'Migratory, predatory schooling legend of the Black Sea and Marmara.', 'Kaşıklar, Rapalalar, İri Tüylü Çapari', 'İstanbul Boğazı, Karadeniz kıyıları', '4/5 Yıldız - Siyah Etli ve Yağlı', 'Eylül ayında fırında veya ızgarada, daha sonra yağlandığında tavada da yapılır.', 'Baked or grilled in September; pan-fried later in the season when it gets fatter.'), ('56cf5aa2-5f63-4d35-b262-22d56a4c41eb', 'Kadife Balığı', 'Tench', 'Tinca tinca', 'Tatlı Su', 'İlkbahar, Yaz', 'Hassas Şamandıralı Takım, Dip Oltası', 'Çamurlu ve sazlık diplerde yaşayan, vücudu koruyucu kaygan bir tabakayla kaplı çok uyanık bir dip balığıdır.', 'A cautious bottom feeding fish living in muddy reed beds.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/1llsqp8zmwo_1784889928084.png', true, '2026-07-23 18:08:50.947245+00', 'Asgari 26 cm', '15 Mart - 15 Haziran', 'Koyu yeşil kadifemsi pul yapısı ve hassas ısırıklarıyla ünlü dip sakini.', 'Dark green velvet-skinned bottom dweller known for subtle bites.', 'Solucan, Kırmızı Kurt, Haşlanmış Mısır, Ekmek İçi', 'İznik Gölü, Mogan Gölü, Abant, Göller Bölgesi durgun sularda', '3/5 Yıldız - Yumuşak ve Yağlı Et', 'Fırında meşe odununda ızgarada veya tavada pişirilir.', 'Grilled over oak charcoal or pan-fried.'), ('571712b9-f7e4-47fd-b0f0-aec5f1acd151', 'Bıyıklı Balık', 'Barbel', 'Barbus barbus', 'Tatlı Su', 'İlkbahar, Yaz', 'LRF, Dip Takımı, Feeder', 'Özellikle nehirlerin taşlık ve akıntılı bölgelerinde yaşar. LRF takımlarına bindiğinde akıntıyı da arkasına alarak inanılmaz bir mücadele sergiler.', 'A very strong fish targeted in rocky and fast-flowing river sections. Offers an intense fight on light gear.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/g6bnqlq883_1784889566734.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 20 cm', '15 Mart - 15 Haziran (Bölgeye göre)', 'Akarsuların dip akıntılarında yaşayan, güçlü bir nehir türü.', 'A strong river species living in fast bottom currents.', 'Solucan, Tavuk Ciğeri, Kaşar Peyniri', 'Melen Çayı, Kızılırmak, Sakarya Nehri ve taşlık dereler', '2/5 Yıldız - Çok Kılçıklı', 'Kılçık sorunu nedeniyle genellikle fileto çıkarılıp kıyma yapılarak köftesi tüketilir.', 'Due to many bones, often filleted and minced to make fish cakes.'), ('57a37f3e-b421-4de6-8cda-a67840bc9939', 'Eşkina', 'Brown Meagre', 'Sciaena umbra', 'Tuzlu Su', 'İlkbahar, Yaz, Sonbahar', 'LRF (Jighead & Silikon), Şamandıralı Kayalık Takımı', 'LRF tutkunlarının kayalık mendireklerde gece avlamayı en çok sevdiği trofe balıklardan biridir. Oltaya takıldığında kayaların altına kaçma eğilimi gösterir.', 'One of the favorite trophy fishes for LRF enthusiasts targeting rocky breakwaters at night.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/fjhq6kz2nu7_1784879001020.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 30 cm (Tavsiye edilen sportif limit)', 'Yıl boyu serbest (Ancak sayılarının azalması nedeniyle limitlere dikkat edilmeli)', 'Kayalık boşluklarında saklanan, gözleri karanlığa alışkın gece avcısı.', 'Nocturnal hunter hiding in rocky crevices, adapted to darkness.', 'Canlı Teke (Karides), Yengeç, Boru Kurdu, Fosforlu Silikonlar', 'Marmara, Karadeniz ve Ege kayalık mendirekleri', '4/5 Yıldız - Lezzetli Beyaz Et', 'Fırında patates ve sebzelerle veya buğulama olarak mükemmeldir.', 'Excellent baked with vegetables or stewed.'), ('62b93879-5871-4dbc-8d23-f499c4c19536', 'İskorpit (Çarpan)', 'Scorpionfish', 'Scorpaena porcus', 'Tuzlu Su', 'İlkbahar, Yaz, Sonbahar', 'LRF (Light Rock Fishing), Yemli Taşaltı Takımı', 'LRF disiplininde gece kayalık meralarda en sık rastlanan balıktır. Oltaya yakalandığında sudan çıkarırken ASLA çıplak elle dokunulmamalı, "fish grip" (balık tutucu) kullanılmalıdır.', 'The most common catch during night LRF in rocky areas. MUST NEVER be handled bare-handed; always use a fish grip due to highly venomous dorsal spines.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/ns1rsew0xl_1784879282714.png', true, '2026-07-22 12:23:32.945782+00', 'Limit Yok', 'Yıl boyu serbest', 'Zehirli dikenleriyle ünlü, kayalık diplerin hareketsiz pusu avcısı. DİKKAT ZEHİRLİDİR.', 'Famous for venomous spines; a motionless ambush predator of rocky bottoms. CAUTION: VENOMOUS.', 'Kokulu Mikro Silikonlar (Isome), Karides, Tavuk Göğsü', 'Tüm Türkiye kıyılarındaki kayalık mendirekler', '5/5 Yıldız - Çorbaların Şahı', 'Sırt ve solungaç dikenleri zehirli olduğu için makasla kesildikten sonra tulum çıkarılıp çorbası yapılır.', 'Spines must be removed with scissors due to venom. Skinned and used to make the best fish soup.'), ('6362a4e6-acb3-4c54-8a6f-77ca3a28fc1d', 'Sinarit', 'Common Dentex', 'Dentex dentex', 'Tuzlu Su', 'İlkbahar, Yaz', 'Slow Jigging, Canlı Yem (Zoka)', 'Çok zeki ve güçlü bir balıktır. Oltaya yakalandığında ilk hamlesi misinayı kayalara sürtüp koparmak olur. Güçlü fluorocarbon lider misinalar şarttır.', 'Very intelligent and powerful. Its first instinct when hooked is to rub the line against rocks, so strong fluorocarbon leaders are essential.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/ssvwmfhajy_1784882923301.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 35 cm (Günlük limit: 5 Kg)', 'Yıl boyu serbest', 'Ege ve Akdeniz taşlıklarının en agresif, devasa dişlere sahip kralı.', 'The king of Aegean and Mediterranean rocky structures, known for its massive canine teeth.', 'Canlı Sübye, Kalamar, Inchiku Jigler', 'Ege Denizi açıkları (Çeşme, Ayvalık), Akdeniz', '5/5 Yıldız - Trofe Lezzet', 'Fırında kaya tuzu altında pişirilmesi veya kiremitte yapılması meşhurdur.', 'Famous for being baked under a rock salt crust or in a clay pot.'), ('7117852e-3282-4c9a-91f3-a9bdf669290b', 'Çapak Balığı', 'Common Bream', 'Abramis brama', 'Tatlı Su', 'İlkbahar, Yaz', 'Şamandıralı Takım, Feeder (Yemlikli) Dip Oltası', 'Yemlemeye (mazmuz) çok hızlı tepki verir. Hassas şamandıra takımları ile durgun sularda sportif avcılığı oldukça keyiflidir.', 'Responds very well to groundbait. Sport fishing with sensitive floats is very popular in still waters.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/xz5q0k3411b_1784889614439.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 20 cm', '15 Mart - 15 Haziran', 'Yassı ve yüksek gövdeli, sürüler halinde gezen göl balığı.', 'Deep-bodied, schooling lake fish that feeds on the bottom.', 'Tatlı Mısır, Kurtçuk (Maggot), Solucan', 'Marmara ve İç Anadolu''daki büyük göller ve yavaş akan nehirler', '2/5 Yıldız - İnce Kılçıklı', 'Tüketimi çok popüler değildir, genelde sportif amaçlı avlanır veya çizik atılarak kızartılır.', 'Not commonly consumed, mostly targeted for sport.'), ('7d7e0105-4105-4868-870e-ba0b112ba227', 'Trakonya', 'Greater Weever', 'Trachinus draco', 'Tuzlu Su', 'Yaz, Sonbahar', 'Yemli Dip Takımı, Çapari', 'Sırtındaki siyah dikenler ve solungaç kapakları şiddetli acı veren zehir taşır (ölü balıkta bile zehir aktiftir). Çapariye sıkça takılır. Asla elle dokunulmamalı, misina kesilerek iade edilmelidir.', 'Black dorsal spines and gill covers carry severe venom (active even after death). Often caught on sabiki rigs. Never touch bare-handed; cut the line if needed.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/6tx5b9fqsp3_1785066228253.png', true, '2026-07-22 12:24:38.112653+00', 'Limit Yok', 'Yıl boyu serbest', 'Türkiye denizlerinin en zehirli dikenlerine sahip, kuma gömülü pusu avcısı. DİKKAT!', 'Possesses the most venomous spines in Turkish seas; a sand-buried ambush predator. DANGER!', 'Tavuk Göğsü, Karides, Sülünes', 'Marmara, Ege ve Akdeniz kumluk sığlıkları', '3/5 Yıldız - Temizlemesi Çok Tehlikeli', 'Eti lezzetlidir fakat zehirli dikenleri nedeniyle amatörlerin el sürmemesi tavsiye edilir.', 'Meat is tasty, but amateurs are strongly advised not to handle it due to extreme venom.'), ('7f1834c5-a688-48ad-a744-f4f03c48ebd5', 'Uskumru', 'Atlantic Mackerel', 'Scomber scombrus', 'Tuzlu Su', 'Sonbahar, Kış', 'Çapari, Hafif Spin', 'Kolyoz ile çok karıştırılır (Uskumrunun gözü daha küçüktür). Marmara''da eskisi kadar çok görülmese de yakalandığında çok hareketli bir av sunar.', 'Often confused with Chub Mackerel. Though less common in Marmara now, it offers a very energetic fight when hooked.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/lesfxtnug_1784883098423.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 20 cm', 'Yıl boyu serbest', 'Sırtındaki kaplan desenleri ile bilinen, yağlı ve sürü halinde gezen pelajik tür.', 'Pelagic schooling species known for its tiger-striped back and oily meat.', 'Tüylü Çapari, Küçük Metal Jigler', 'Marmara, Çanakkale Boğazı, Karadeniz', '5/5 Yıldız - Çok Sağlıklı ve Yağlı', 'Kurutularak çirozu yapılır, ızgarası efsanedir.', 'Traditionally sun-dried as "çiroz" or perfectly grilled.'), ('823bf59b-caf9-439d-91fb-d448644448f6', 'Fener Balığı', 'Anglerfish', 'Lophius piscatorius', 'Tuzlu Su', 'Kış, İlkbahar', 'Derin Su Dip Takımı, Parakete', 'Görüntüsü ürkütücü olsa da denizlerin en lezzetli etine sahip balıklarındandır. Çok derin sularda yaşadığı için sportif avcılığı nadirdir.', 'Despite its scary appearance, it has one of the most delicious meats. Rarely caught sport fishing due to its deep habitat.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/e8n6jq2czpr_1784889769772.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 50 cm', 'Yıl boyu serbest', 'Kafasındaki doğal oltasıyla avlanan, derin suların kamuflaj ustası.', 'Deep-water camouflage master that hunts using a natural lure on its head.', 'Bütün Sübye, Kalamar, İzmarit', 'Ege ve Akdeniz derinlikleri, Marmara', '5/5 Yıldız - Efsanevi Lezzet', 'Kafası çorbada kullanılır, gövdesi fileto çıkarılıp tavada veya kavurma olarak pişirilir.', 'Head is used for soup, while the tail is filleted and pan-fried.'), ('84d25b34-42b7-46a4-b191-930631da33a2', 'Abant Alası', 'Abant Trout', 'Salmo trutta abanticus', 'Tatlı Su', 'İlkbahar, Yaz', 'Fly-fishing, LRF, Döner Kaşık (Mepps)', 'Özellikle göl ve derelerde sinek oltası (fly-fishing) ile avlanması büyük keyif veren, koruma altındaki endemik bir tür. LRF (Light Rock Fishing) takımlarıyla mikro sahtelere harika tepki verir.', 'An endemic, protected species that offers great sport for fly-fishing and LRF enthusiasts in high altitude lakes and streams.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/dnuu25ouned_1784878912269.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 25 cm (Günlük limit: 3 Adet)', '1 Ekim - 28 Şubat (Orman içi sularda)', 'Sadece Türkiye''ye özgü, soğuk su seven endemik bir alabalık türü.', 'Endemic cold-water trout species native only to Turkey.', 'Suni Sinek, Küçük Döner Kaşıklar, Mikro Silikonlar', 'Abant Gölü, Yedigöller ve Bolu/Düzce yüksek rakımlı dereler', '5/5 Yıldız - Yüksek Yağ Oranı', 'Tereyağında hafifçe tavada kızartılır veya kiremitte fırınlanır.', 'Lightly pan-fried in butter or baked in a clay pot.'), ('856487bb-cd1c-47c9-88ca-781b731f22f6', 'Kırmızı Benekli Alabalık', 'Brown Trout', 'Salmo trutta fario', 'Tatlı Su', 'İlkbahar, Yaz', 'Fly-fishing, Ultra Light LRF, Mepps Kaşık (0-1 No)', 'Buz gibi berrak derelerde yaşamını sürdüren, inanılmaz ürkek ve zeki bir alabalık türüdür. Sinek oltası (Fly fishing) sporu için en değerli balıktır.', 'An extremely wary and intelligent native trout, highly prized by fly anglers.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/89kepyfxrzy_1784889947138.png', true, '2026-07-23 18:08:50.476574+00', 'Asgari 20 cm (Günlük limit: 3 Adet)', '1 Ekim - 28 Şubat (Orman içi sularda)', 'Dağ derelerinin ve buz gibi kaynak sularının yerli kraliçesi.', 'The native queen of cold mountain streams and spring waters.', 'Suni Sinek (Dry/Nymph), Mikro Kaşıklar, Küçük Silikonlar', 'Doğu Karadeniz dereleri, Toros dağ dereleri, Munzur, Kaçkarlar', '5/5 Yıldız - Müthiş Lezzet ve Kırmızı Et', 'Tereyağında hafifçe tavada kızartılır veya kiremitte fırınlanır.', 'Best pan-fried in fresh butter or clay pot baked.'), ('85a4220e-b0db-4412-b5cb-e6534dc5ba15', 'Fangri (Fangri Mercan)', 'Couch''s Seabream', 'Pagrus pagrus', 'Tuzlu Su', 'İlkbahar, Sonbahar', 'Derin Su Yemli Takım, Inchiku, Slow Jig', 'Sinarit ve Trança ile aynı yaşam alanını paylaşır. Çenesi çok kuvvetlidir, iğneyi kırabilir. Tekne avcılarının en prestijli avlarından biridir.', 'Shares habitat with Dentex. Has incredibly strong jaws that can crush hooks. A highly prestigious catch for boat anglers.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/32ac0rxk10c_1784879025597.png', true, '2026-07-22 12:23:32.945782+00', 'Asgari 35 cm', 'Yıl boyu serbest', 'Pembe rengi ve güçlü yapısıyla derin taşlıkların değerli sakini.', 'Valuable resident of deep rocky areas with a striking pink color and strong build.', 'Canlı Kalamar, Bütün Sübye, Karides', 'Ege Denizi açıkları, Saros Körfezi', '5/5 Yıldız - Üst Düzey Beyaz Et', 'Izgarası efsanedir, büyük boyları fırında tuzda pişirilir.', 'Legendary on the grill; larger specimens are baked in a salt crust.'), ('868f4fd8-0828-4b82-baf1-3656624878bf', 'Vatoz (İğneli Vatoz)', 'Common Stingray', 'Dasyatis pastinaca', 'Tuzlu Su', 'İlkbahar, Yaz', 'Surfcasting, Ağır Dip Takımı', 'Gece sörf (surfcasting) avında oltaya devasa bir ağırlık olarak biner, dipten kaldırması çok zordur. Sudan çıkarıldığında kuyruğundaki zehirli iğneden kesinlikle uzak durulmalıdır.', 'Bends surfcasting rods heavily during night sessions; very hard to lift off the bottom. Extreme caution required regarding its venomous tail spine.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/l76sbvf3nb_1784883134686.png', true, '2026-07-22 12:24:38.112653+00', 'Limit Yok', 'Yıl boyu serbest', 'Kumluk deniz tabanında uçarcasına yüzen, kuyruğunda zehirli iğne taşıyan kıkırdaklı tür.', 'Cartilaginous species gliding over sandy bottoms, armed with a venomous tail stinger.', 'Bütün Sardalya, Yengeç, İri Sülünes', 'Ege ve Akdeniz kumsalları', '1/5 Yıldız - Tüketilmez', 'Genellikle eti için avlanmaz, Catch & Release (Yakala ve Bırak) yapılır.', 'Not typically eaten; exclusively a Catch & Release species.'), ('89b81315-f08b-4b35-b0ca-f66bdd9098e7', 'Alabalık (Gökkuşağı)', 'Rainbow Trout', 'Oncorhynchus mykiss', 'Tatlı Su', 'İlkbahar, Sonbahar', 'Fly-fishing, LRF (1-5g), Mepps Kaşık', 'Hızlı akan sularda ultra hafif LRF takımları ve döner kaşıklarla avlanması muhteşem bir aksiyon sunar. Akıntıya karşı yüzmeyi sever.', 'Provides excellent action in fast-flowing streams when targeted with ultralight gear and spinners.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/up2cwnipzzr_1784889438801.png', true, '2026-07-22 12:21:18.943312+00', 'Limit Yok (İstilacı/Üretim türü olarak kabul edilir)', 'Doğal popülasyonlar için 1 Ekim - 28 Şubat', 'Akarsu ve göllerin hızlı, çevik ve obur balığı.', 'Fast, agile, and voracious fish of streams and lakes.', 'Suni Sinek (Nymph, Dry Fly), Mepps 1-2 No, Alabalık Hamuru', 'Soğuk ve akıntılı dereler, baraj gölleri', '4/5 Yıldız - Lezzetli ve Kılçıksız', 'Mısır ununa bulanıp tavada kızartılır veya fırında tereyağlı yapılır.', 'Coated in cornmeal and pan-fried or baked with butter.'), ('8c631ae8-32d7-4714-beb5-2a7d7f29beff', 'Yayın Balığı', 'Wels Catfish', 'Silurus glanis', 'Tatlı Su', 'Yaz (Özellikle sıcak yaz geceleri)', 'Ağır Dip Takımı (Catfish Rig), Clonk (Şaplak)', 'Akarsularda kamp avcılığı yapanların rüyasıdır. Gece beslenir, titreşime ve kokuya çok duyarlıdır. Büyüklüğü 2 metreyi, ağırlığı 100 kiloyu geçebilir.', 'A dream for river campers. Nocturnal and highly sensitive to vibration and smell. Can grow over 2 meters and 100 kg.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/6udrmo03qqx_1784895701629.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 90 cm', '15 Mart - 15 Haziran', 'Tatlı sularımızın en büyüğü; uzun bıyıklı, pulsuz, devasa dip canavarı.', 'The largest in our freshwaters; a giant, scaleless bottom monster with long barbels.', 'Canlı Balık (Kızılkanat vs.), İri Solucan Demeti, Tavuk Ciğeri, Sülük', 'Sakarya Nehri, Kızılırmak, Seyhan Nehri', '4/5 Yıldız - Kılçıksız, Tavuk Eti Gibi', 'Kalın dilimler halinde kesilip şişte mangalı veya mısır unlu tavası yapılır.', 'Cut into thick steaks for skewers on the grill, or pan-fried with cornmeal.'), ('90492e84-8073-4036-a5ae-314f6cb527c1', 'Zargana', 'Garfish', 'Belone belone', 'Tuzlu Su', 'Yaz, Sonbahar', 'Şamandıralı Top (Zargana Topu), İnce LRF', 'Özellikle sonbaharda kıyılardan zargana topu arkasına bağlanan iğnesiz ipek (sadece dişlerine takılır) ile avlanması çok meşhurdur. Su yüzeyinde zıplayarak muazzam bir görsel şölen sunar.', 'Famous for being caught with hookless silk threads (which tangle in their teeth) trailed behind a float. Provides a visual spectacle by jumping across the surface.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/hp6dq9vdxcq_1784883167630.png', true, '2026-07-22 12:21:18.943312+00', 'Limit Yok (Sportif sınır bulunmuyor)', 'Yıl boyu serbest', 'İnce uzun gagasıyla su yüzeyinde gezen, kılıç şeklindeki kıyı balığı.', 'Sword-shaped coastal fish with a long beak, cruising the surface.', 'İpek (Turuncu/Sarı), Gümüş Balığı, Kuyruk Altı, Midye Kenarı', 'Tüm kıyılar (Marmara, Ege, Karadeniz, Akdeniz)', '3/5 Yıldız - Fosforlu Yeşil Kılçıklı', 'Kılçıkları yeşil renklidir, zehirli değildir. Tavada bütün olarak kızartılır.', 'Has harmless fluorescent green bones. Pan-fried whole.'), ('92bcbbec-ad0a-438a-8b0b-a61860e027d9', 'Yılan Balığı', 'European Eel', 'Anguilla anguilla', 'Tatlı Su', 'İlkbahar, Yaz, Sonbahar', 'Gece Yemli Dip Oltası', 'Okyanusta doğup tatlı su nehirlerimize göç eden, gece kayalık ve çamurlu diplerde yemli oltalarla yakalanan egzotik bir türdür.', 'An exotic catadromous species targeted at night with heavy bottom bait rigs.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/n4ldcm82ua_1784895632761.png', true, '2026-07-23 18:08:51.036604+00', 'Asgari 50 cm', 'Yıl boyu serbest', 'Denizlerden nehirlere göç eden son derece güçlü ve yağlı yılanımsı balık.', 'Catadromous snake-like fish migrating between oceans and freshwaters.', 'Canlı Balık, Sülük, Solucan, Balık Parçaları', 'Manavgat Nehir Ağzı, Köyceğiz Gölü, Sakarya Nehri, Asi Nehri', '5/5 Yıldız - Çok Yüksek Yağ Oranı ve Güçlü Lezzet', 'Izgarada kömür ateşinde kendi yağında pişirilir veya füme yapılır.', 'Grilled over charcoal in its own natural fat or smoked.'), ('9c503e41-02a8-4e4a-9312-0e866d08d948', 'Sardalya', 'European Pilchard', 'Sardina pilchardus', 'Tuzlu Su', 'Yaz, Sonbahar', 'Çapari (10-11 numara iğne)', 'Temmuz ve Ağustos aylarında aşırı yağlandığı için mangalı muazzam olur. İnce çaparilerle sürüye denk gelindiğinde oltayı saniyeler içinde doldurur.', 'Becomes incredibly fatty in July and August, making it perfect for BBQ. When a school is found, light sabiki rigs will fill up in seconds.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/d3hrzsek8hn_1784882258941.png', true, '2026-07-22 12:24:38.112653+00', 'Asgari 11 cm', 'Yıl boyu serbest', 'Ege ve Çanakkale''nin gümüş renkli, bol yağlı, sürü halinde gezen incisi.', 'The silver-colored, highly oily schooling pearl of the Aegean and Dardanelles.', 'Beyaz ve Yeşil Tüylü Çapari', 'Çanakkale Boğazı, Kuzey Ege, Saros Körfezi', '5/5 Yıldız - Omega 3 Deposu', 'Asma yaprağına sarılıp mangalda veya pulları temizlenmeden ızgarada yapılır.', 'Wrapped in vine leaves and grilled on charcoal, or grilled whole without scaling.'), ('9f63647c-57ee-4ae6-b415-afa7d9a30d2a', 'Akya', 'Leerfish', 'Lichia amia', 'Tuzlu Su', 'Yaz, Sonbahar', 'Ağır Spinning, Shore Jigging, Canlı Yem', 'Kıyıdan ve tekneden büyük sahteler veya canlı yemlerle avlanan, inanılmaz mücadeleci bir trofe balığıdır. Oltaya bindiğinde yorucu bir direnç gösterir.', 'A massive trophy fish targeted with large lures or live bait, known for its incredible fighting spirit.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/96nu1ii9o4t_1784889314927.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 50 cm', 'Yıl boyu serbest', 'Kıyıların en güçlü ve saldırgan pelajik avcılarından biri.', 'One of the most powerful and aggressive pelagic predators of the coasts.', 'Canlı Zargana, İstavrit, Su Üstü Popper Sahteler', 'Akdeniz ve Ege Kıyıları, Antalya, İzmir', '3/5 Yıldız - Sıkı ve Kuru Et', 'Kuşbaşı doğranıp şişte veya fırında bol zeytinyağı ile pişirilmesi önerilir.', 'Best cubed and grilled on skewers or baked with plenty of olive oil.'), ('a01f5fa3-31e3-41c8-8c3a-6313ad839d0c', 'Zurna Balığı', 'Brushtooth Lizardfish', 'Saurida undosquamis', 'Tuzlu Su', 'Yaz, Sonbahar', 'LRF (Jighead, Mikro Jig), Spinning', 'Dibe çok yakın bekleyip üzerinden geçen sahtelere şimşek hızıyla fırlar. Akdeniz kıyılarında LRF ve hafif spin yapanların en sık karşılaştığı istilacı (Lessepsian) türlerdendir.', 'Waits near the bottom and strikes passing lures with lightning speed. One of the most common invasive catches for LRF anglers on the Mediterranean coast.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/fk3hpprfjwh_1784896594010.png', true, '2026-07-22 12:24:38.112653+00', 'Limit Yok (İstilacı Tür)', 'Yıl boyu serbest', 'Kızıldeniz göçmeni, silindir gövdeli ve jilet gibi dişlere sahip agresif avcı.', 'Lessepsian (Red Sea) migrant; aggressive predator with a cylindrical body and razor-like teeth.', 'Kırmızı/Pembe Silikonlar, Metal Jigler', 'Akdeniz kıyıları (Antalya, Mersin, İskenderun)', '2/5 Yıldız - Fazla Kılçıklı', 'Kılçıkları çoktur, genelde sportif zevki için tutulur.', 'Very bony, usually targeted purely for sport.'), ('a064e825-582e-43f5-a786-e470dc3b2715', 'Minekop (Kötek)', 'Shi Drum', 'Umbrina cirrosa', 'Tuzlu Su', 'Sonbahar, Kış', 'Surfcasting, Yemli İnce Dip Takımı', 'Kumsal ve kırma taşlık bölgeleri sever. Ağzı aşağı doğru olduğu için kumu eşeleyerek beslenir. Eşkina ve Granyöz ile akrabadır.', 'Prefers sandy and mixed rocky beaches. Its downward-facing mouth is perfect for rooting in the sand. Closely related to the Meagre and Brown Meagre.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/mrt7tldhcjg_1784894714789.png', true, '2026-07-22 12:23:32.945782+00', 'Asgari 25 cm', 'Yıl boyu serbest', 'Çenesinin altındaki tek kısa bıyığı ile bilinen kumluk bölge avcısı.', 'Sandy bottom hunter known for a single short barbel under its chin.', 'Sülünes, Boru Kurdu, Yengeç', 'Karadeniz kıyıları (Şile, Ağva), Marmara ve Ege', '5/5 Yıldız - Muazzam Lezzet', 'Fırında zeytinyağlı ve sebzeli buğulaması harika olur.', 'Wonderful when baked as a stew with olive oil and vegetables.'), ('a43c8e96-8f45-40c0-b08c-6c4842168884', 'Trança', 'Pink Dentex', 'Dentex gibbosus', 'Tuzlu Su', 'İlkbahar, Yaz', 'Derin Su Jigging, Parakete', 'Derin taşlıkların etrafında gezer. Yaşı ilerledikçe kafasında karakteristik bir hörgüç oluşur. Tekne avcılarının en büyük hayallerinden biridir.', 'Roams around deep rocky structures. Develops a characteristic head hump as it ages. A top dream catch for boat anglers.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/jey9oeehajn_1784883062119.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 35 cm', 'Yıl boyu serbest', 'Sinarit''in akrabası olan, kafası hörgüçlü derin su trofesi.', 'A relative of the Dentex, this deep-water trophy features a distinctive head hump.', 'Canlı Kalamar, Sübye', 'Ege (Gökçeada, Çanakkale açıkları)', '5/5 Yıldız - Çok Yüksek Kalite', 'Dilimlenip ızgarada veya sebzelerle fırında pişirilir.', 'Steaked and grilled, or baked with vegetables.'), ('a69ac0de-449e-44aa-a502-b2c1ac9c1120', 'Baraküda (Iskarmoz)', 'European Barracuda', 'Sphyraena sphyraena', 'Tuzlu Su', 'Yaz, Sonbahar', 'Spinning (At-Çek), Shore Jigging', 'Özellikle gece ve sabahın ilk ışıklarında sığlıklara girerek yavru balık sürülerini sıkıştırır. İnce uzun sahtelere (jerkbait) çok sert tepki verir.', 'Hunts in shallows during the night and at first light. Reacts aggressively to long, slender jerkbaits.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/mkw82qy9b5f_1784889386701.png', true, '2026-07-22 12:23:32.945782+00', 'Limit Yok (Sportif tavsiye: 40 cm altı salınmalı)', 'Yıl boyu serbest', 'Kıyıların ok gibi hızlı, keskin dişli sürü avcısı.', 'Arrow-fast, sharp-toothed schooling predator of the coasts.', 'Uzun İnce Sahteler (Minnow), Su Üstü (WTD), Jigler', 'Akdeniz ve Ege kıyıları, liman içleri', '3/5 Yıldız - Kuru ama Lezzetli', 'Eti biraz kurudur, fırında zeytinyağı ve domates sosuyla pişirilmesi önerilir.', 'Meat is slightly dry; best baked with olive oil and tomato sauce.'), ('ba90d4b0-00ff-4126-b5be-eb180607d72b', 'Barbunya', 'Red Mullet', 'Mullus barbatus', 'Tuzlu Su', 'Yaz, Sonbahar', 'Yemli İnce Dip Takımı', 'Kumluk diplerde sürüler halinde dolaşır. Çok hassas vuruşları olduğu için ince uçlu hassas kamışlarla avlanmalıdır.', 'Travels in schools over sandy bottoms. Should be targeted with sensitive tip rods due to subtle bites.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/j5mq9s8mkd_1784889542542.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 13 cm', '15 Nisan - 31 Ağustos (Trol yasağı dönemi)', 'Pembe/kırmızı rengi ve çene altı bıyıklarıyla bilinen dip balığı.', 'Pink/red bottom-dwelling fish known for its chin barbels.', 'Karides, Sülünes, Boru Kurdu', 'Ege, Marmara ve Akdeniz kıyıları', '5/5 Yıldız - Tavaların Prensi', 'Mısır unu ile tavada bütün olarak nar gibi kızartılır.', 'Fried whole in a pan with corn flour until crispy.'), ('c5ccddfd-f072-47a1-80b2-1ba901652a3d', 'Turna', 'Northern Pike', 'Esox lucius', 'Tatlı Su', 'İlkbahar, Sonbahar', 'Spinning (At-Çek)', 'Otluk ve sazlık kenarlarında pusu kurup avına aniden saldırır. Keskin dişleri misinayı kolayca kestiği için avında mutlaka çelik tel (wire leader) kullanılmalıdır.', 'Ambush predator that attacks suddenly from weeds. A steel wire leader is absolutely mandatory due to its razor-sharp teeth.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/4u8qx54lmfa_1784883078984.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 40 cm (Günlük limit: 5 Adet)', '15 Aralık - 31 Mart (Üreme dönemi)', 'Sazlıkların arasına gizlenen, tatlı suların kamuflajlı tatlı su timsahı.', 'The freshwater crocodile; a camouflaged ambush predator hiding among reeds.', 'Döner Kaşık (Mepps 3-4-5), Sasi (Silikon), Maket Balıklar', 'İç Anadolu ve Marmara''daki göller, sazlık göletler, Terkos', '3/5 Yıldız - Lezzetli Fakat Kılçıklı', 'Y şeklinde kılçıkları vardır, tulum çıkarılıp kızartılması veya köftesi önerilir.', 'Has Y-shaped bones; best skinned and fried, or minced for patties.'), ('c9a4fde7-10a2-4f84-9c12-ed584433e6b5', 'Hamsi', 'European Anchovy', 'Engraulis encrasicolus', 'Tuzlu Su', 'Kış', 'Çapari', 'Sportif kıyı avcılığında kış aylarında Karadeniz kıyılarından ince çaparilerle alınabilir. Suyun soğumasıyla yağlanır ve lezzetlenir.', 'Can be caught with delicate sabiki rigs from the shore during winter. Becomes fattier and tastier as water cools.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/4ht4ludm4a_1784879146079.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 9 cm', '15 Nisan - 31 Ağustos (Endüstriyel avcılık yasağı)', 'Karadeniz''in gümüş renkli, sürü halinde göç eden efsanesi.', 'The silver-colored, migrating schooling legend of the Black Sea.', 'Yemsiz (Tüylü Çapari)', 'Tüm Karadeniz, Marmara Denizi', '5/5 Yıldız - Kültürel Miras', 'Mısır unuyla tavada dizilerek (Hamsi Kuşu) veya ızgarada yapılır.', 'Coated in corn flour and pan-fried in a circular pattern, or grilled.'), ('ccc89dfe-697e-49ae-8165-ad97dc777542', 'Tatlı Su Kefali (Kasna)', 'European Chub', 'Squalius cephalus', 'Tatlı Su', 'İlkbahar, Yaz, Sonbahar', 'LRF (0.5-5g), Fly-Fishing, Mikro Maketler', 'Taşlık ve akıntılı nehirlerde, köprü altlarında veya suya sarkan ağaç dallarının gölgesinde bekler. LRF ve Fly-fishing ile su üstü sahtelere yaptığı sert vuruşlar sebebiyle avı en zevkli tatlı su türlerindendir.', 'Waits under overhanging trees or in river currents. Famous for its aggressive surface strikes, making it a top target for LRF and Fly-fishing.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/jje3agxjvgf_1784882998929.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 20 cm', '15 Mart - 15 Haziran (İç sular)', 'Akarsu avcılığının gözdesi, yüzeyden beslenmeyi seven zeki avcı.', 'The star of stream fishing, an intelligent predator that feeds off the surface.', 'Su Üstü Mikro Maketler, Döner Kaşık (Mepps), Çekirge (Fly)', 'Melen Çayı, Karadeniz dereleri ve iç anadolu akarsuları', '2/5 Yıldız - Bol Kılçıklı', 'Eti pek lezzetli olmadığı için Catch & Release (Yakala ve Bırak) yapılması en doğrusudur.', 'Not highly valued for meat; Catch & Release is strongly encouraged.'), ('dd9d23de-943e-40cf-a63e-51533af40a9d', 'Dil Balığı', 'Common Sole', 'Solea solea', 'Tuzlu Su', 'Kış, İlkbahar', 'Çok İnce Dip Takımı (Hırsızlı)', 'Ağzı çok küçük olduğu için oldukça küçük iğneler (ör: 8-10 numara) kullanılmalıdır. Gündüz kuma gömülür, gece avlanmaya çıkar.', 'Requires very small hooks due to a tiny mouth. Buries in sand during the day and hunts at night.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/73oapwd4eu2_1784889687419.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 20 cm', '1 Ocak - 1 Şubat (Bölgesel kısıtlamalar uygulanabilir)', 'Kuma gömülerek yaşayan, yassı formlu usta kamuflajcı.', 'Flat bottom-dwelling fish that lives buried in sand, mastering camouflage.', 'Küçük Karides, Sülünes, Boru Kurdu', 'Ege ve Akdeniz kumluk sığlıkları', '5/5 Yıldız - Kılçıksız, Lokum Gibi', 'Kılçıksız olduğu için tereyağlı tavada Sole Meunière usulü yapılır.', 'Cooked Sole Meunière style in butter due to being boneless.'), ('eb71a62c-03fa-446c-b421-c8b3d5a1063e', 'Orfoz', 'Dusky Grouper', 'Epinephelus marginatus', 'Tuzlu Su', 'Hiçbiri (Hedef dışı avdır)', 'Hedeflenmez (Oltaya gelirse iğne nazikçe çıkarılıp hemen salınmalıdır)', 'Cinsiyet değiştirebilen, yıllarca aynı yuvada yaşayan, denizlerimizin sembol türlerindendir. Nesli tehlike altında olduğu için uluslararası anlaşmalarla koruma altındadır. Yanlışlıkla yakalanırsa suya iade edilmesi yasal bir zorunluluktur.', 'A symbol of the Mediterranean that can change sex and live in the same cave for years. It is strictly protected under international law; if caught accidentally, it must be released immediately.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/pf0j2qyoj2e_1784881896504.png', true, '2026-07-22 12:24:38.112653+00', 'AVLANMASI YASAK (Koruma Altında)', 'Yıl boyu her türlü avcılığı kesinlikle yasaktır', 'Akdeniz''in devasa ve dost canlısı kaya balığı. AVLANMASI TAMAMEN YASAKTIR.', 'Giant and friendly rock fish of the Mediterranean. STRICTLY PROTECTED, NO FISHING.', 'Hedeflenmez', 'Akdeniz ve Ege''nin taşlık bölgeleri, Kaş, Kalkan', 'Yasak Tür', 'Tüketilmesi ve satılması yasaktır.', 'Consumption and sale are strictly prohibited by law.'), ('ebd20263-669e-465b-8a45-71cb3b2f0354', 'Şabut Balığı', 'Euphrates Barbel', 'Arabibarbus grypus', 'Tatlı Su', 'İlkbahar, Yaz', 'Sazan Montajı, Yemli Dip Oltası', 'Fırat ve Dicle nehrinde yaşayan, pullu ve bıyıklı yapısıyla yüksek ekonomik ve lezzet değerine sahip endemik bir tatlı su türüdür.', 'An endemic barbel species highly valued for its gastronomy and fighting power.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/pny4ohdnldl_1784895440575.png', true, '2026-07-23 18:08:50.748289+00', 'Asgari 30 cm', '15 Mart - 15 Haziran', 'Mezopotamya sularına özgü lezzeti ve gücüyle ünlü bıyıklı balık.', 'A powerful barbell species native to Mesopotamian waters.', 'Haşlanmış Mısır, Özel Sazan Hamurları, Solucan, Yengeç', 'Fırat ve Dicle Nehri, Atatürk Barajı, Keban Barajı, Birecik', '5/5 Yıldız - Yörenin En Lezzetli Balığı', 'Izgarada meşe kömüründe pişirilir veya fırında sebzeli buğulama yapılır.', 'Grilled over charcoal or baked with fresh vegetables.'), ('edeff7ec-a8d0-47c5-ac0c-ed7c013ce02e', 'Çizgili Mercan (Mırmır)', 'Striped Seabream', 'Lithognathus mormyrus', 'Tuzlu Su', 'Yaz, Sonbahar', 'Surfcasting, İnce Dip Takımı, LRF', 'Özellikle gece avlarında surfcasting disiplini ile kumsallardan uzağa atılarak avlanır. Kumu eşeleyerek beslendiği için dipten gelen yemlere duyarlıdır.', 'Targeted from sandy beaches, especially during night fishing, using the surfcasting discipline.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/6dh52ubf7vw_1784889667997.png', true, '2026-07-22 12:21:18.943312+00', 'Asgari 15 cm', 'Yıl boyu serbest', 'Kumluk sahillerin gümüş renkli, dikey çizgili efendisi.', 'Silver-colored, vertically striped master of sandy beaches.', 'Boru Kurdu, Sülünes, Yengeç', 'Ege ve Akdeniz kumsalları, Marmara Denizi', '4/5 Yıldız - Beyaz ve Sıkı Et', 'Izgarada veya fırında az yağlı pişirmeye çok uygundur.', 'Highly suitable for grilling or baking.'), ('f811a32c-eae7-4a11-a1dd-f14bc507c58f', 'Tatlı Su Levreği (Perç)', 'European Perch', 'Perca fluviatilis', 'Tatlı Su', 'İlkbahar, Yaz, Sonbahar', 'LRF (Light Rock Fishing), Döner Kaşık, Silikon Sahteler', 'Sürü halinde gezen ve mikro yemlere gözü kapalı atlayan çok keyifli bir LRF balığıdır. Dikenli sırt yüzgecine dikkat edilmelidir.', 'Schooling lake predators that offer non-stop action on ultralight lures.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/p4xb3mwny1b_1784895511093.png', true, '2026-07-23 18:08:50.611236+00', 'Asgari 18 cm', '15 Mart - 30 Nisan', 'Çizgili vücudu ve turuncu yüzgeçleriyle göllerin obur avcısı.', 'A voracious lake predator with tiger stripes and bright orange fins.', 'Mikro Silikonlar (2-5cm), Döner Kaşıklar (Mepps 1-2 No), Canlı Gümüş Balığı', 'Sapanca Gölü, Terkos Gölü, Uluabat, Eğirdir, İç Anadolu gölleri', '4/5 Yıldız - Beyaz ve Sıkı Et', 'Derisi yüzüldükten sonra mısır ununa bulanıp tavada çıtır kızartılır.', 'Skin removed, coated in cornmeal and pan-fried crispy.'), ('ffe60f46-0ad4-47de-a187-2ee5d97ac40d', 'Somon (Karadeniz Somonu)', 'Black Sea Salmon (Sea Trout)', 'Salmo labrax', 'Tuzlu Su', 'Kış, İlkbahar', 'Ağır Spin (At-Çek), Shore Jigging', 'Tatlı suda doğar, denize inip devasa boyutlara ulaşır ve üremek için tekrar nehre döner (Anadrom). Kış aylarında Karadeniz kıyılarından at-çek ile avcılığı çok popülerdir.', 'An anadromous species. Hatches in rivers, grows massive in the sea, and returns to freshwater to spawn. Highly targeted by shore spin anglers in winter.', 'https://mrbbioabvgbutijbbcpm.supabase.co/storage/v1/object/public/user_uploads/fishes/lq76smgzhz_1784882946835.png', true, '2026-07-22 12:24:38.112653+00', 'Asgari 20 cm (Tatlı Suda)', '1 Ekim - 28 Şubat (Tatlı Sular)', 'Doğu Karadeniz''in hırçın derelerinde doğup denize göçen efsanevi alabalık türü.', 'Legendary trout species that hatches in the fierce streams of the Eastern Black Sea and migrates to the sea.', 'Büyük Döner Kaşıklar, Kaşık Sahteler (Hansen), Maketler', 'Doğu Karadeniz (Trabzon, Rize, Artvin kıyıları ve dereleri)', '5/5 Yıldız - Somon Kalitesi', 'Fırında zeytinyağı, limon ve defne yaprağıyla pişirilmesi harikadır.', 'Excellent baked with olive oil, lemon, and bay leaves.');